  await evaluate("document.querySelector('#starterMix').click(); true"); await delay(900);
  stats=await evaluate('AlquimiaReactiva.getStats()');
  console.log('Tras mezcla inicial:',stats);
  assert.equal(stats.discovered,5); assert.equal(stats.instances,1);
  assert.equal(await evaluate("document.querySelector('.element-node .node-name').textContent"),'GitHub Copilot');
