  assert.equal((await evaluate('AlquimiaReactiva.getStats()')).instances,3);
  const points=await evaluate("['code','ai'].map(id=>{const n=document.querySelector(`.element-node[data-element=${id}]`);const r=n.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2}})");
  for(const p of points){await send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',clickCount:1});await send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',clickCount:1});await delay(180);}
  await delay(300);
  stats=await evaluate('AlquimiaReactiva.getStats()');
  console.log('Tras combinar con clics:',stats);
  assert.equal(stats.instances,2); assert.equal(stats.discovered,5);
  await evaluate("const i=document.querySelector('#searchInput');i.value='copilot';i.dispatchEvent(new Event('input',{bubbles:true}));true");
  assert.equal(await evaluate("document.querySelectorAll('.inventory-item').length"),1);
  await evaluate("document.querySelector('#searchClear').click(); document.querySelector('#sortButton').click(); true");
  assert.equal(await evaluate("document.querySelector('#sortLabel').textContent"),'A–Z');
  await evaluate("document.querySelector('#hintButton').click(); true");
  assert.equal(await evaluate("document.querySelector('#hintCard').hidden"),false);
  assert.ok((await evaluate("document.querySelector('#hintFormula').textContent")).includes('Código'));
  await evaluate("document.querySelector('#useHint').click(); true");
  assert.equal(await evaluate("document.querySelector('#hintCard').hidden"),true);
  await evaluate("document.querySelector('#journalTab').click(); true");
  assert.equal(await evaluate("document.querySelector('#journalView').hidden"),false);
  assert.ok(await evaluate("document.querySelectorAll('.journal-entry').length>=2"));
  await evaluate("document.querySelector('#helpButton').click(); true");
  assert.equal(await evaluate("document.querySelector('#helpDialog').open"),true);
  await evaluate("document.querySelector('#helpDialog .primary-button').click(); true");
  assert.equal(await evaluate("document.querySelector('#helpDialog').open"),false);
  const desktop=await evaluate("({scrollWidth:document.body.scrollWidth,width:innerWidth,height:document.body.scrollHeight,viewport:innerHeight})");
  assert.ok(desktop.scrollWidth<=desktop.width,'Desbordamiento horizontal en escritorio');
  await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true}); await delay(250);
  const mobile=await evaluate("({scrollWidth:document.body.scrollWidth,width:innerWidth,boardHeight:document.querySelector('#board').getBoundingClientRect().height,inventoryColumns:getComputedStyle(document.querySelector('#inventory')).gridTemplateColumns})");
